"""Build three independent, portable theatre bookshelf prototypes (stdlib + Pillow)."""
from pathlib import Path
import json
import re
import hashlib
from PIL import Image

ROOT = Path(__file__).resolve().parent
PARENT = ROOT.parent
ASSETS = ROOT / 'assets'
ASSETS.mkdir(exist_ok=True)
for name in ('oldsong.woff2', 'wenkai.woff2'):
    (ASSETS / name).write_bytes((PARENT / 'assets' / name).read_bytes())
for name in 'abcd':
    with Image.open(PARENT / 'assets' / f'{name}.png') as im:
        im.thumbnail((720, 1080))
        im.convert('RGB').save(ASSETS / f'cover-{name}.webp', quality=85)

source = (PARENT / 'data.js').read_text('utf-8')
book_source = re.search(r'const books=(\[.*?\]);', source).group(1)
BOOKS = json.loads(re.sub(r'([,{])(\w+):', r'\1"\2":', book_source).replace("'", '"'))
for b, art in zip(BOOKS, ['d','d','c','b','d','c']):
    b['art'] = art

